QDw.woff2\",\"fontWeight\":\"500\",\"fontStyle\":\"normal\",\"fontFamily\":\"Quicksand\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand-500-normal.svg\"},{\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/6xK-dSZaM9iE8KbpRA_LJ3z8mH9BOJvgkCEv18S0wx40QDw.woff2\",\"fontWeight\":\"600\",\"fontStyle\":\"normal\",\"fontFamily\":\"Quicksand\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand-600-normal.svg\"},{\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/6xK-dSZaM9iE8KbpRA_LJ3z8mH9BOJvgkBgv18S0wx40QDw.woff2\",\"fontWeight\":\"700\",\"fontStyle\":\"normal\",\"fontFamily\":\"Quicksand\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand-700-normal.svg\"}],\"source\":\"custom\"}]}}},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}','Custom Styles','','publish','closed','closed','','wp-global-styles-spectra-one','','','2025-01-30 23:25:18','2025-01-31 07:25:18','',0,'https://wordpress.mycodelicforest.org/wp-global-styles-spectra-one/',0,'wp_global_styles','',0),(22,1,'2025-01-27 00:13:45','2025-01-27 00:13:45','','mycodelic-forest-hero-cover','','inherit','open','closed','','mycodelic-forest-hero-cover','','','2025-01-27 00:13:45','2025-01-27 00:13:45','',0,'https://wordpress.mycodelicforest.org/wp-content/uploads/2024/10/mycodelic-forest-hero-cover.jpg',0,'attachment','image/jpeg',0),(24,1,'2025-01-27 00:16:30','2025-01-27 00:16:30','<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|large\",\"padding\":{\"top\":\"var:preset|spacing|x-large\",\"bottom\":\"var:preset|spacing|x-large\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"black\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignwide has-black-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--x-large);padding-bottom:var(--wp--preset--spacing--x-large)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|large\",\"left\":\"var:preset|spacing|large\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|small\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|xx-small\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"className\":\"wp-block-heading\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}}},\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color\">Welcome to the forest</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}}},\"textColor\":\"white\"} -->\n<p class=\"has-white-color has-text-color has-link-color\"><strong>Mycodelic Forest</strong> is a Burning Man theme camp rooted in anarchy—no boss, no babysitters, and definitely no coddling. We’re all about pushing boundaries, respecting each other’s limits, and saying exactly what’s on our minds. We don’t tolerate violence or threats, but we sure as hell celebrate radical self-reliance, direct communication, and creative chaos. Think of it as a rowdy family where everyone is essential to the mycelial network—come as you are, and don’t be afraid to speak up (or shut up) when you need to.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"textAlign\":\"right\",\"textColor\":\"white\",\"className\":\"is-style-outline\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}}}} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link has-white-color has-text-color has-link-color has-text-align-right wp-element-button\">Learn More</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Home','','publish','closed','closed','','home','','','2025-02-04 20:12:21','2025-02-05 04:12:21','',0,'https://wordpress.mycodelicforest.org/?page_id=24',0,'page','',0),(30,1,'2025-01-27 00:38:30','2025-01-27 00:38:30','<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|large\",\"padding\":{\"top\":\"var:preset|spacing|x-large\",\"bottom\":\"var:preset|spacing|medium\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"black\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-black-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--x-large);padding-bottom:var(--wp--preset--spacing--medium)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|medium\",\"left\":\"var:preset|spacing|medium\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|xx-small\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-bottom:var(--wp--preset--spacing--xx-small)\"><!-- wp:uagb/advanced-heading {\"block_id\":\"f2277332\",\"classMigrate\":true,\"headingDescToggle\":false,\"headingColor\":\"#FFFFFF\",\"headingTag\":\"h1\"} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-f2277332\"><h1 class=\"uagb-heading-text\">MYCODELIC FOREST</h1></div>\n<!-- /wp:uagb/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|medium\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\" style=\"padding-right:var(--wp--preset--spacing--medium)\">Convince us you need a drink</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|xx-small\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-bottom:var(--wp--preset--spacing--xx-small)\"><!-- wp:columns {\"isStackedOnMobile\":false,\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"32px\",\"left\":\"32px\"}}}} -->\n<div class=\"wp-block-columns is-not-stacked-on-mobile\"><!-- wp:column {\"style\":{\"spacing\":[]}} -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"1px\",\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"textColor\":\"background\",\"fontSize\":\"x-small\"} -->\n<p class=\"has-background-color has-text-color has-x-small-font-size\" style=\"font-style:normal;font-weight:500;letter-spacing:1px;text-transform:uppercase\">Get Connected</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:navigation {\"ref\":125,\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"left\"}} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":[]}} -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"1px\",\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"textColor\":\"background\",\"fontSize\":\"x-small\"} -->\n<p class=\"has-background-color has-text-color has-x-small-font-size\" style=\"font-style:normal;font-weight:500;letter-spacing:1px;text-transform:uppercase\">About Us</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:navigation {\"ref\":124,\"overlayMenu\":\"never\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|xx-small\"}},\"layout\":{\"type\":\"flex\",\"setCascadingProperties\":true,\"justifyContent\":\"left\",\"orientation\":\"vertical\"}} /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|xx-small\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-bottom:var(--wp--preset--spacing--xx-small)\"><!-- wp:columns {\"isStackedOnMobile\":false,\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"32px\",\"left\":\"32px\"}}}} -->\n<div class=\"wp-block-columns is-not-stacked-on-mobile\"><!-- wp:column {\"style\":{\"spacing\":[]}} -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"1px\",\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"textColor\":\"background\",\"fontSize\":\"x-small\"} -->\n<p class=\"has-background-color has-text-color has-x-small-font-size\" style=\"font-style:normal;font-weight:500;letter-spacing:1px;text-transform:uppercase\">Resources</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:navigation {\"ref\":114,\"overlayMenu\":\"never\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|xx-small\"}},\"layout\":{\"type\":\"flex\",\"setCascadingProperties\":true,\"justifyContent\":\"left\",\"orientation\":\"vertical\"}} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":[]}} -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"1px\",\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"textColor\":\"background\",\"fontSize\":\"x-small\"} -->\n<p class=\"has-background-color has-text-color has-x-small-font-size\" style=\"font-style:normal;font-weight:500;letter-spacing:1px;text-transform:uppercase\">Support</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:navigation {\"ref\":116,\"overlayMenu\":\"never\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|xx-small\"}},\"layout\":{\"type\":\"flex\",\"setCascadingProperties\":true,\"justifyContent\":\"left\",\"orientation\":\"vertical\"}} /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|xx-small\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"x-small\"} -->\n<p class=\"has-text-align-center has-x-small-font-size\">© 2025 ·</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:site-title {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"x-small\"} /-->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"x-small\"} -->\n<p class=\"has-text-align-center has-x-small-font-size\">· All rights reserved</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Footer','','publish','closed','closed','','footer','','','2025-02-13 21:42:29','2025-02-14 05:42:29','',0,'https://wordpress.mycodelicforest.org/footer/',0,'wp_template_part','',0),(31,1,'2025-01-27 00:39:14','2025-01-27 00:39:14','<!-- wp:paragraph -->\n<p>We are The Mycodelic Forest, a Burning Man theme camp located around the 3\'oclock sector in Black Rock City.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The Mycodelic Forest is a family of spontaneous and vigorously creative people. At all times, we are a peaceful, tolerant family with respect for life and the environment. Burning Man could not exist without the love and devotion of each entity and we try to inspire, by being inspired. Each person is responsible for everything that is them, and through what\'s uniquely realized, we want to provide magic; of thought, of creation, and of evolution. We want everyone to be proud of what a community filled with responsibility, love and acceptance can create. We encourage immediacy of experience. Be here, be now. Join us in the Mycodelic Forest.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We are a group of dedicated, civic minded burners that believe in the interconnectedness of all organisms. Our group has been attending Burning Man as The Mycodelic Forest for many years now, but spent our first year as The Enchanted Forest Funki. This website is a place to learn about all things related to the Mycodelic Forest Burning Man theme camp and to organize and coordinate our members. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','About Us','','publish','closed','closed','','about-us','','','2025-02-09 20:02:13','2025-02-10 04:02:13','',0,'https://wordpress.mycodelicforest.org/?page_id=31',0,'page','',0),(34,1,'2025-01-27 00:55:46','2025-01-27 00:55:46','<!-- wp:gravityforms/form {\"formId\":\"4\",\"inputPrimaryColor\":\"#204ce5\"} /-->','Contact','','publish','closed','closed','','contact','','','2025-01-27 13:08:21','2025-01-27 21:08:21','',0,'https://wordpress.mycodelicforest.org/?page_id=34',0,'page','',0),(35,1,'2025-01-27 00:54:34','2025-01-27 00:54:34','<!-- wp:uagb/advanced-heading {\"block_id\":\"ddab48f1\",\"classMigrate\":true,\"headingDescToggle\":false} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-ddab48f1\"><h2 class=\"uagb-heading-text\">2024 Roster</h2></div>\n<!-- /wp:uagb/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>[civi_group_contacts group_id=\"45\"]</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Roster','','publish','closed','closed','','roster','','','2025-01-27 18:34:49','2025-01-28 02:34:49','',0,'https://wordpress.mycodelicforest.org/?page_id=35',0,'page','',0),(38,1,'2025-01-27 00:56:50','2025-01-27 00:56:50','<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','FAQs','','publish','closed','closed','','faqs','','','2025-01-30 23:19:04','2025-01-31 07:19:04','',0,'https://wordpress.mycodelicforest.org/?page_id=38',0,'page','',0),(40,1,'2025-01-27 00:57:17','2025-01-27 00:57:17','','Resources','','publish','closed','closed','','resources','','','2025-01-27 00:57:18','2025-01-27 00:57:18','',0,'https://wordpress.mycodelicforest.org/?page_id=40',0,'page','',0),(42,1,'2025-01-27 00:58:50','2025-01-27 00:58:50','<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"blockGap\":\"0\"},\"dimensions\":{\"minHeight\":\"0px\"},\"typography\":{\"fontSize\":\"0px\"}},\"backgroundColor\":\"black\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-black-background-color has-background\" style=\"min-height:0px;margin-top:0px;margin-bottom:0px;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0;font-size:0px\"><!-- wp:group {\"align\":\"wide\",\"className\":\"swt-block-row\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group alignwide swt-block-row\"><!-- wp:heading {\"level\":1,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|background\"}}}},\"textColor\":\"background\"} -->\n<h1 class=\"wp-block-heading has-background-color has-text-color has-link-color\">MYCODELIC FOREST</h1>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"swt-block-row\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|large\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group swt-block-row\"><!-- wp:navigation {\"ref\":59,\"textColor\":\"white\",\"overlayTextColor\":\"black\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|medium\"}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"right\"}} /-->\n\n<!-- wp:buttons {\"SWTHideMob\":true} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\"></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Header','','publish','closed','closed','','header','','','2025-01-30 22:49:55','2025-01-31 06:49:55','',0,'https://wordpress.mycodelicforest.org/header/',0,'wp_template_part','',0),(44,1,'2025-01-26 17:43:35','2025-01-27 01:43:35','<!-- wp:gravityforms/form {\"formId\":\"3\",\"inputPrimaryColor\":\"#204ce5\"} /-->','Register','','publish','closed','closed','','register','','','2025-01-26 17:43:36','2025-01-27 01:43:36','',0,'https://wordpress.mycodelicforest.org/?page_id=44',0,'page','',0),(50,1,'2025-01-26 18:25:16','2025-01-27 02:25:16','<!-- wp:paragraph -->\n<p>If you are new to Mycodelic forest you firstly need a Sponsor who is camping with us who has camped with us before. Sponsors typically can only sponsor one new person into the camp, Think of your Sponsor as the first person you\'ll go to when you have questions.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','How do I join Mycodelic Forest','','publish','open','closed','','how-do-i-join-mycodelic-forest','','','2025-01-26 18:25:17','2025-01-27 02:25:17','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=50',0,'ufaq','',0),(53,1,'2025-01-26 18:26:17','2025-01-27 02:26:17','<!-- wp:paragraph -->\n<p>Come say hi to us on Playa and make friends! Maybe next year will be your year to camp with us</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','But I don\'t know any of you to Sponsor me','','publish','open','closed','','but-i-dont-know-any-of-you-to-sponsor-me','','','2025-01-26 18:26:18','2025-01-27 02:26:18','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=53',0,'ufaq','',0),(54,1,'2025-01-26 18:33:05','2025-01-27 02:33:05','<!-- wp:paragraph -->\n<p>You\'ll want to talk to our Welcome Wagon, Bloodbucket, through your Sponsor. Once you are connected with Bloodbucket you will get all of the important links including our Discord, you will need to download it if you dont have it, where we do most of our communication, Once you are in the Discord you\'ll want to connect with our Ticketmaster ASAP, and Pay your camp dues ASAP, Pay attention to when we announce meetings in the Discord and get your info into the Burn Plan ASAP</p>\n<!-- /wp:paragraph -->','Ok I have a Sponsor, now what?','','publish','open','closed','','ok-i-have-a-sponsor-now-what','','','2025-01-26 18:33:06','2025-01-27 02:33:06','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=54',0,'ufaq','',0),(57,1,'2025-01-26 18:36:05','2025-01-27 02:36:05','<!-- wp:paragraph -->\n<p>Yes! AND... We typically pool our water into a communal water cooler, if you don\'t want to you don\'t have to share your own water but if you drink from the communal water it is expected you contribute to it. We recommend you bring at least a gallon of water a day. Most camp members bring extra but DO NOT RELY ON ANYONE ELSE FOR WATER.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Do I need to bring my own water?','','publish','open','closed','','do-i-need-to-bring-my-own-water','','','2025-01-26 18:36:07','2025-01-27 02:36:07','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=57',0,'ufaq','',0),(58,1,'2025-01-26 18:38:59','2025-01-27 02:38:59','<!-- wp:paragraph -->\n<p>Yes! You are expected to bring your own meals. Please also bring something to contribute to the Smoker if you can. See Kitchen FAQ for questions about preparing your food</p>\n<!-- /wp:paragraph -->','Do I need to bring my own food?','','publish','open','closed','','do-i-need-to-bring-my-own-food','','','2025-01-26 18:39:00','2025-01-27 02:39:00','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=58',0,'ufaq','',0),(59,1,'2025-01-26 18:38:49','2025-01-27 02:38:49','<!-- wp:navigation-link {\"label\":\"Home\",\"url\":\"/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"About\",\"type\":\"page\",\"id\":31,\"url\":\"https://wordpress.mycodelicforest.org/about-us/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Blog\",\"type\":\"page\",\"id\":133,\"url\":\"https://wordpress.mycodelicforest.org/blog/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"FAQs\",\"type\":\"page\",\"id\":38,\"url\":\"https://wordpress.mycodelicforest.org/faqs/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Resources\",\"type\":\"page\",\"id\":40,\"url\":\"https://wordpress.mycodelicforest.org/resources/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Roster\",\"type\":\"page\",\"id\":35,\"url\":\"https://wordpress.mycodelicforest.org/roster/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Contact\",\"type\":\"page\",\"id\":34,\"url\":\"https://wordpress.mycodelicforest.org/contact/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->','Header navigation','','publish','closed','closed','','header-navigation','','','2025-01-30 17:10:11','2025-01-31 01:10:11','',0,'https://wordpress.mycodelicforest.org/?p=59',0,'wp_navigation','',0),(62,1,'2025-01-26 18:41:47','2025-01-27 02:41:47','<!-- wp:paragraph -->\n<p> We have a whole kitchen setup. It\'s not fancy, but we have a large two-burner outdoor propane range, a smaller 3 burner propane range, and a small propane oven with a 2 burner propane range on top. There will be two mini fridges, a small top loading freezer, and a medium-sized top loading freezer. We will be providing refreezable ice cube trays to cut back on the grey water if you have coolers. There will be an electric hot water pot, and yes...an espresso machine.</p>\n<!-- /wp:paragraph -->','Kitchen! What\'s in it?','','publish','open','closed','','kitchen-whats-in-it','','','2025-01-26 18:41:48','2025-01-27 02:41:48','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=62',0,'ufaq','',0),(63,1,'2025-01-26 18:47:45','2025-01-27 02:47:45','<!-- wp:paragraph -->\n<p>Camp will have Power you can plug into to charge your devices. Camp Provides homebrew beer to serve at the bar. Camp will have a 10x10x10 spot under shade for your tent. If you bring a significant other, you can take up a 10x20 space with your giant Chateau. RV and Bus Spots are on a case by case basis. We do have a shower that is pack in and pack out your water, ask Meeshu how to use it. There are pots and pans to use (Make sure to clean them) and you should bring your own cup/dishes but if you can\'t we have some to spare. There is NO SINK see Dishes FAQ for more info, </p>\n<!-- /wp:paragraph -->','What else does camp provide','','publish','open','closed','','what-else-does-camp-provide','','','2025-01-26 18:51:21','2025-01-27 02:51:21','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=63',0,'ufaq','',0),(64,1,'2025-01-26 18:48:16','2025-01-27 02:48:16','<!-- wp:paragraph -->\n<p>There is no sink. We used to bring a sink but camp members were unable to use the sink responsibly with low water usage. Many people left dishes in the sink to \'soak\'. Camp has a number of spray bottles that we will have available with different fluids in them. There is a spray bottle for plain water (Blue), for soapy water (Green), and for vinegar (Red). Immediately after using your dish, you should spray it lightly with water and wipe it out with a disinfectant wipe or paper towels. We will have lots of wipes to be provided for you so that you can promptly do your dishes. DON\'T LEAVE DIRTY DISHES.</p>\n<!-- /wp:paragraph -->','Dishes','','publish','open','closed','','dishes','','','2025-01-26 18:48:17','2025-01-27 02:48:17','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=64',0,'ufaq','',0),(65,1,'2025-01-26 18:52:41','2025-01-27 02:52:41','<!-- wp:paragraph -->\n<p>ONE HUNDRED MILLION DOLLARSS MWUAHAHAHAHA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','How Much are camp dues','','publish','open','closed','','how-much-are-camp-dues','','','2025-01-26 18:53:15','2025-01-27 02:53:15','',0,'https://wordpress.mycodelicforest.org/?post_type=ufaq&#038;p=65',0,'ufaq','',0),(66,1,'2025-01-26 18:51:46','2025-01-27 02:51:46','','DPX00464','','inherit','open','closed','','dpx00464','','','2025-01-26 18:51:46','2025-01-27 02:51:46','',0,'https://wordpress.mycodelicforest.org/wp-content/uploads/2024/10/DPX00464.jpg',0,'attachment','image/jpeg',0),(77,1,'2025-01-26 21:09:51','2025-01-27 05:09:51','{\"fontFamily\":\"Quicksand, sans-serif\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand.svg\"}','Quicksand','','publish','closed','closed','','quicksand','','','2025-01-26 21:09:51','2025-01-27 05:09:51','',0,'https://wordpress.mycodelicforest.org/quicksand/',0,'wp_font_family','',0),(78,1,'2025-01-26 21:09:52','2025-01-27 05:09:52','{\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/6xK-dSZaM9iE8KbpRA_LJ3z8mH9BOJvgkKEo18S0wx40QDw.woff2\",\"fontWeight\":\"300\",\"fontStyle\":\"normal\",\"fontFamily\":\"Quicksand\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand-300-normal.svg\"}','quicksand;normal;300;100%;U+0-10FFFF','','publish','closed','closed','','quicksandnormal300100u0-10ffff','','','2025-01-26 21:09:52','2025-01-27 05:09:52','',77,'https://wordpress.mycodelicforest.org/quicksandnormal300100u0-10ffff/',0,'wp_font_face','',0),(79,1,'2025-01-26 21:09:53','2025-01-27 05:09:53','{\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/6xK-dSZaM9iE8KbpRA_LJ3z8mH9BOJvgkP8o18S0wx40QDw.woff2\",\"fontWeight\":\"400\",\"fontStyle\":\"normal\",\"fontFamily\":\"Quicksand\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand-400-normal.svg\"}','quicksand;normal;400;100%;U+0-10FFFF','','publish','closed','closed','','quicksandnormal400100u0-10ffff','','','2025-01-26 21:09:53','2025-01-27 05:09:53','',77,'https://wordpress.mycodelicforest.org/quicksandnormal400100u0-10ffff/',0,'wp_font_face','',0),(80,1,'2025-01-26 21:09:54','2025-01-27 05:09:54','{\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/6xK-dSZaM9iE8KbpRA_LJ3z8mH9BOJvgkM0o18S0wx40QDw.woff2\",\"fontWeight\":\"500\",\"fontStyle\":\"normal\",\"fontFamily\":\"Quicksand\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand-500-normal.svg\"}','quicksand;normal;500;100%;U+0-10FFFF','','publish','closed','closed','','quicksandnormal500100u0-10ffff','','','2025-01-26 21:09:54','2025-01-27 05:09:54','',77,'https://wordpress.mycodelicforest.org/quicksandnormal500100u0-10ffff/',0,'wp_font_face','',0),(81,1,'2025-01-26 21:09:55','2025-01-27 05:09:55','{\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/6xK-dSZaM9iE8KbpRA_LJ3z8mH9BOJvgkCEv18S0wx40QDw.woff2\",\"fontWeight\":\"600\",\"fontStyle\":\"normal\",\"fontFamily\":\"Quicksand\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand-600-normal.svg\"}','quicksand;normal;600;100%;U+0-10FFFF','','publish','closed','closed','','quicksandnormal600100u0-10ffff','','','2025-01-26 21:09:55','2025-01-27 05:09:55','',77,'https://wordpress.mycodelicforest.org/quicksandnormal600100u0-10ffff/',0,'wp_font_face','',0),(82,1,'2025-01-26 21:09:56','2025-01-27 05:09:56','{\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/6xK-dSZaM9iE8KbpRA_LJ3z8mH9BOJvgkBgv18S0wx40QDw.woff2\",\"fontWeight\":\"700\",\"fontStyle\":\"normal\",\"fontFamily\":\"Quicksand\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/quicksand\\/quicksand-700-normal.svg\"}','quicksand;normal;700;100%;U+0-10FFFF','','publish','closed','closed','','quicksandnormal700100u0-10ffff','','','2025-01-26 21:09:56','2025-01-27 05:09:56','',77,'https://wordpress.mycodelicforest.org/quicksandnormal700100u0-10ffff/',0,'wp_font_face','',0),(86,1,'2025-01-27 12:33:20','2025-01-27 20:33:20','{\"fontFamily\":\"Megrim, system-ui\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/megrim\\/megrim.svg\"}','Megrim','','publish','closed','closed','','megrim','','','2025-01-27 12:33:20','2025-01-27 20:33:20','',0,'https://wordpress.mycodelicforest.org/megrim/',0,'wp_font_family','',0),(87,1,'2025-01-27 12:33:21','2025-01-27 20:33:21','{\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/46kulbz5WjvLqJZlaGXgd0RY1g.woff2\",\"fontWeight\":\"400\",\"fontStyle\":\"normal\",\"fontFamily\":\"Megrim\",\"preview\":\"https:\\/\\/s.w.org\\/images\\/fonts\\/wp-6.7\\/previews\\/megrim\\/megrim-400-normal.svg\"}','megrim;normal;400;100%;U+0-10FFFF','','publish','closed','closed','','megrimnormal400100u0-10ffff','','','2025-01-27 12:33:21','2025-01-27 20:33:21','',86,'https://wordpress.mycodelicforest.org/megrimnormal400100u0-10ffff/',0,'wp_font_face','',0),(90,1,'2025-01-27 12:49:59','2025-01-27 20:49:59','<!-- wp:paragraph -->\n<p>Burning Man co-founder Larry Harvey wrote the Ten Principles in 2004 as guidelines for the newly-formed Regional Network. They were crafted not as a dictate of how people should be and act, but as a reflection of the community’s ethos and culture as it had organically developed since the event’s inception.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/radical-inclusion.html\">Radical Inclusion</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Anyone may be a part of Burning Man. We welcome and respect the stranger. No prerequisites exist for participation in our community.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/gifting.html\">Gifting</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Burning Man is devoted to acts of gift giving. The value of a gift is unconditional. Gifting does not contemplate a return or an exchange for something of equal value.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/decommodification.html\">Decommodification</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>In order to preserve the spirit of gifting, our community seeks to create social environments that are unmediated by commercial sponsorships, transactions, or advertising. We stand ready to protect our culture from such exploitation. We resist the substitution of consumption for participatory experience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/radical-self-reliance.html\">Radical Self-reliance</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Burning Man encourages the individual to discover, exercise and rely on his or her inner resources.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/radical-self-expression.html\">Radical Self-expression</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Radical self-expression arises from the unique gifts of the individual. No one other than the individual or a collaborating group can determine its content. It is offered as a gift to others. In this spirit, the giver should respect the rights and liberties of the recipient.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/communal-effort.html\">Communal Effort</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Our community values creative cooperation and collaboration. We strive to produce, promote and protect social networks, public spaces, works of art, and methods of communication that support such interaction.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/civic-responsibility.html\">Civic Responsibility</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We value civil society. Community members who organize events should assume responsibility for public welfare and endeavor to communicate civic responsibilities to participants. They must also assume responsibility for conducting events in accordance with local, state and federal laws.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/leaving-no-trace.html\">Leaving No Trace</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Our community respects the environment. We are committed to leaving no physical trace of our activities wherever we gather. We clean up after ourselves and endeavor, whenever possible, to leave such places in a better state than when we found them.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/participation.html\">Participation</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Our community is committed to a radically participatory ethic. We believe that transformative change, whether in the individual or in society, can occur only through the medium of deeply personal participation. We achieve being through doing. Everyone is invited to work. Everyone is invited to play. We make the world real through actions that open the heart.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><a href=\"https://mycodelicforest.org/The-10-Principles-of-Burning-Man/immediacy.html\">Immediacy</a></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Immediate experience is, in many ways, the most important touchstone of value in our culture. We seek to overcome barriers that stand between us and a recognition of our inner selves, the reality of those around us, participation in society, and contact with a natural world exceeding human powers. No idea can substitute for this experience.</p>\n<!-- /wp:paragraph -->','10 Principles','','publish','closed','closed','','10-principles','','','2025-01-27 12:50:00','2025-01-27 20:50:00','',0,'https://wordpress.mycodelicforest.org/?page_id=90',0,'page','',0),(99,1,'2025-01-27 18:27:05','2025-01-28 02:27:05','{\"fontFamily\":\"ALITIDE\"}','ALITIDE','','publish','closed','closed','','alitide','','','2025-01-27 18:27:05','2025-01-28 02:27:05','',0,'https://wordpress.mycodelicforest.org/alitide/',0,'wp_font_family','',0),(100,1,'2025-01-27 18:27:06','2025-01-28 02:27:06','{\"fontFamily\":\"ALITIDE\",\"fontStyle\":\"normal\",\"fontWeight\":\"400\",\"src\":\"https:\\/\\/wordpress.mycodelicforest.org\\/wp-content\\/uploads\\/fonts\\/ALITIDE.ttf\"}','alitide;normal;400;100%;U+0-10FFFF','','publish','closed','closed','','alitidenormal400100u0-10ffff','','','2025-01-27 18:27:06','2025-01-28 02:27:06','',99,'https://wordpress.mycodelicforest.org/alitidenormal400100u0-10ffff/',0,'wp_font_face','',0),(112,1,'2025-01-28 16:01:12','2025-01-29 00:01:12','<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:html -->\n<iframe src=\"https://calendar.google.com/calendar/embed?src=7959a3b3b88e14ee2cd5e33195e9a204e449efbba32b8335357c8dc1093f7fde%40group.calendar.google.com&ctz=America%2FLos_Angeles\" style=\"border: 0\" width=\"800\" height=\"600\" frameborder=\"0\" scrolling=\"no\"></iframe>\n<!-- /wp:html --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Calendar','','publish','closed','closed','','calendar','','','2025-01-29 11:23:50','2025-01-29 19:23:50','',0,'https://wordpress.mycodelicforest.org/?page_id=112',0,'page','',0),(114,1,'2025-01-29 11:22:06','2025-01-29 19:22:06','<!-- wp:navigation-link {\"label\":\"Calendar\",\"type\":\"page\",\"id\":112,\"url\":\"https://wordpress.mycodelicforest.org/calendar/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Glassfrog\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Holocracy\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Discord\",\"url\":\"Discord\",\"kind\":\"custom\"} /-->','Footer navigation','','publish','closed','closed','','footer-navigation','','','2025-01-29 11:22:06','2025-01-29 19:22:06','',0,'https://wordpress.mycodelicforest.org/?p=114',0,'wp_navigation','',0),(115,1,'2025-01-29 11:22:07','2025-01-29 19:22:07','<!-- wp:navigation-link {\"label\":\"Knowledge Base\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Contact Support\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"F\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"TOS\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->','Footer navigation 2','','publish','closed','closed','','footer-navigation-2','','','2025-01-29 11:22:07','2025-01-29 19:22:07','',0,'https://wordpress.mycodelicforest.org/?p=115',0,'wp_navigation','',0),(116,1,'2025-01-29 11:22:10','2025-01-29 19:22:10','<!-- wp:navigation-link {\"label\":\"Knowledge Base\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Contact Support\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"FAQs\",\"type\":\"page\",\"id\":38,\"url\":\"https://wordpress.mycodelicforest.org/faqs/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->','Footer navigation 3','','publish','closed','closed','','footer-navigation-3','','','2025-01-29 11:22:10','2025-01-29 19:22:10','',0,'https://wordpress.mycodelicforest.org/?p=116',0,'wp_navigation','',0),(124,1,'2025-01-29 11:26:43','2025-01-29 19:26:43','<!-- wp:navigation-link {\"label\":\"About Us\",\"type\":\"page\",\"id\":31,\"url\":\"https://wordpress.mycodelicforest.org/about-us/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Roster\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->','Footer navigation 4','','publish','closed','closed','','footer-navigation-4','','','2025-02-13 21:31:12','2025-02-14 05:31:12','',0,'https://wordpress.mycodelicforest.org/?p=124',0,'wp_navigation','',0),(125,1,'2025-01-29 11:26:44','2025-01-29 19:26:44','<!-- wp:navigation-link {\"label\":\"Register\",\"url\":\"/register\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"About Us\",\"type\":\"page\",\"id\":31,\"url\":\"https://wordpress.mycodelicforest.org/about-us/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"\",\"url\":\"#\",\"kind\":\"custom\",\"isTopLevelLink\":true,\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} /-->','Footer navigation 5','','publish','closed','closed','','footer-navigation-5','','','2025-02-13 21:42:30','2025-02-14 05:42:30','',0,'https://wordpress.mycodelicforest.org/?p=125',0,'wp_navigation','',0),(129,1,'2025-01-30 12:39:43','2025-01-30 20:39:43','<!-- wp:paragraph -->\n<p>Hello Trevor,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We\'re happy to let you know you that Mycodelic Forest will be invited to the Stewards Sale for Burning Man 2025: Tomorrow Today!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>As a theme camp in good standing (YAY!), you will receive 16 total tickets to support your camp’s invaluable contributions to Black Rock City. We’re excited to see you return to help create the magic again.&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Theme camps are one of the primary cultural contributors to Burning Man and we are providing 100% of your requested tickets so your campmates don’t need to compete with the open market to attend BRC. We hope this eases the pressure you may have felt in previous years trying to get tickets through other channels.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>When’s the Stewards Sale?</strong>&nbsp;Mark your calendars! The Stewards Sale invitation period will be February 21-28 when you can invite your campmates to purchase Stewards tickets, and the Stewards Sale will take place March 5-8. More information about general ticketing to Black Rock City will be coming later this week, and we’ll follow up in a couple weeks with instructions about next steps.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Thanks for bringing your gifts and interactivity once again. Don’t forget to join us for a town hall meeting this Saturday; details are at the bottom of this email. You’ll hear the latest news and updated and exciting bits and pieces about this year\'s Black Rock City. 2025’s going to be the best burn ever!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>The 2025 Placement Team</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Town Hall Details</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Who: You and other core collaborators</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>What: Burning Man Community Town Hall</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>When: Saturday, February 1 @ 10am PT / 1pm ET / 7pm CET </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Where:<a href=\"https://email.burningman.org/t/t-l-shilydd-tttdgutkr-r/\" target=\"_blank\" rel=\"noreferrer noopener\"> https://burningman.zoom.us/j/89145030576?pwd=5jxbHrVetVOKVuRXCKkLbzzbEbUcK9.1</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->','Mycodelic Forest\'s Access to Black Rock City’s 2025 Stewards Sale','','publish','open','open','','mycodelic-forests-access-to-black-rock-citys-2025-stewards-sale','','','2025-01-30 12:39:44','2025-01-30 20:39:44','',0,'https://wordpress.mycodelicforest.org/?p=129',0,'post','',0),(133,1,'2025-01-30 17:08:08','2025-01-31 01:08:08','','Blog','','publish','closed','closed','','blog','','','2025-01-30 17:50:33','2025-01-31 01:50:33','',0,'https://wordpress.mycodelicforest.org/?page_id=133',0,'page','',0),(193,1,'2025-01-30 20:42:40','2025-01-31 04:42:40','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"spectra-one\",\"tagName\":\"header\",\"SWTTransparentHeader\":true} /-->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-bottom:0\"><!-- wp:themepunch/revslider {\"alias\":\"frontpage-hero-slider\"} -->\n<div class=\"wp-block-themepunch-revslider revslider\" data-modal=\"false\" data-slidertitle=\"Frontpage Hero Slider\" style=\"\">[rev_slider alias=\"frontpage-hero-slider\" slidertitle=\"Frontpage Hero Slider\"][/rev_slider]</div>\n<!-- /wp:themepunch/revslider --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-bottom:0\"><!-- wp:post-content {\"style\":{\"spacing\":{\"block