"wide\"} -->\n<div class=\"wp-block-query alignwide\"><!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":1,\"minimumColumnWidth\":null}} -->\n<!-- wp:post-featured-image {\"isLink\":true,\"height\":\"400px\",\"style\":{\"border\":{\"radius\":\"8px\"}}} /-->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|xx-small\",\"padding\":{\"top\":\"var:preset|spacing|xx-small\",\"bottom\":\"var:preset|spacing|medium\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--xx-small);padding-bottom:var(--wp--preset--spacing--medium)\"><!-- wp:post-terms {\"term\":\"category\",\"className\":\"is-style-swt-post-terms-pill\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"fontSize\":\"x-small\"} /-->\n\n<!-- wp:post-title {\"level\":4,\"isLink\":true,\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|xx-small\",\"bottom\":\"var:preset|spacing|xx-small\"}}},\"textColor\":\"heading\"} /-->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|xx-small\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:post-author {\"avatarSize\":24,\"showAvatar\":false,\"fontSize\":\"x-small\"} /-->\n\n<!-- wp:paragraph {\"fontSize\":\"x-small\"} -->\n<p class=\"has-x-small-font-size\">·</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:post-date {\"format\":\"M j, Y\",\"fontSize\":\"x-small\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:post-excerpt /--></div>\n<!-- /wp:group -->\n<!-- /wp:post-template -->\n\n<!-- wp:query-no-results -->\n<!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Add text or blocks that will display when a query returns no results.\"} -->\n<p class=\"has-text-align-center\"></p>\n<!-- /wp:paragraph -->\n<!-- /wp:query-no-results --></div>\n<!-- /wp:query --></div>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"spectra-one\",\"tagName\":\"footer\"} /-->','Blog Home','Displays the latest posts as either the site homepage or as the \"Posts page\" as defined under reading settings. If it exists, the Front Page template overrides this template when posts are shown on the homepage.','publish','closed','closed','','home','','','2025-01-30 23:14:15','2025-01-31 07:14:15','',0,'https://wordpress.mycodelicforest.org/home/',0,'wp_template','',0),(236,1,'2025-02-02 16:36:09','2025-02-03 00:36:09','<!-- wp:paragraph -->\n<p>Dear Trevor,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Thank you for all your hard work as a camp to bring your best to Burning Man for Black Rock City 2024: Curiouser &amp; Curiouser! Theme camps, like the art, mutant vehicles, and creative contributions of so many, are what make Black Rock City vibrant and create the space for connection. We\'re pleased to inform you that <strong>Mycodelic Forest is in Good Standing</strong> with the Placement Team as a Theme Camp, which means you met all or most of the criteria listed below to be in Good Standing. <a href=\"https://burningman.org/event/participate/camps/placement-process/criteria/#cgs\" target=\"_blank\" rel=\"noreferrer noopener\">Detailed descriptions of the Criteria to be in Good Standing can be found here</a>.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>What does your Good Standing mean?</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Good Standing means you are eligible for Stewards Sale tickets and future placement as a returning theme camp. In order to remain in Good Standing, your camp must attend Black Rock City again as your camp sometime in the next three years. That means your camp can take this year and next year off and retain your Good Standing if you wish. You do not have to return next year to maintain your standing, and we do encourage breaks so you can rest and make space for other theme camps. Please read this story in the Burning Man Journal, “<a href=\"https://journal.burningman.org/2024/02/black-rock-city/building-brc/adapting-to-growth/\" target=\"_blank\" rel=\"noreferrer noopener\">Adapting to Growth and Change in Black Rock City</a>,” to see why we’re encouraging theme camps to take breaks.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>What are the criteria to be in Good Standing?</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Did your camp show up and use your reserved space?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Did your camp do what you said you were going to do on your questionnaire? <em> </em>(Interactivity &amp; frontage available to the entire Burning Man community) <em>This criteria only applies to Theme Camps. </em> </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Did your camp uphold our community\'s principles and cultural norms? (including neighborliness, keeping sound within set limits, easily resolving any boundary disputes that arise, and being public and inclusive)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Did your camp honor our Decommodification principle?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Was your camp a strain on Burning Man\'s organizational resources? (requiring extra attention or energy from Rangers, DPW, the Playa Restoration team, and others)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>How were your camp’s MOOP results from the Playa Restoration team?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Did your camp abide by the terms of your Setup Access Passes?</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>How did we arrive at your standing?</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>After each event, the Placement team collects and reviews feedback from the community and other Burning Man Project departments. Feedback comes through various sources including direct communication from individuals, notes from Placement’s Exploration &amp; Engagement Research Squad (PEERS), the public feedback from the Black Rock City 2024: Post-event Survey, and Placement’s Neighborhood Feedback Form.<br><br>The “Post-playa Report” that is expected from all camps also gives you a chance to let us know how things went including any successes and challenges you acknowledged. We also acknowledge that the information we collect has limits. All of these pieces of information come together to get the most holistic picture of your camp possible to arrive at your final camp standing for the year.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Feedback Snapshots</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We are offering snapshots at the end of this email that share some of the highlights of feedback we’ve received. Not every camp has specific feedback, and that’s okay if you don’t. If you do have feedback, we hope it helps you receive the kudos you deserve and allows you to reflect on the things you could improve upon.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If your Theme Camp had MOOP discovered by the Playa Restoration Team, details can be found in an email sent on December 3 with the subject, “Leave No Trace Results for Mycodelic Forest.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>Next Steps</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Please be sure to fill out Placement’s Statement of Intent through your Burner Profile for 2025 to let us know if you plan to return or take the year off by Thursday, January 16, 2025 before 12pm (noon) Pacific Time. The SOI can be found in your <a href=\"https://profiles.burningman.org/participate/brc\" target=\"_blank\" rel=\"noreferrer noopener\">Burner Profile under the BRC Participation page</a>. More information on the SOI can be found in our <a href=\"https://help.burningman.org/hc/en-us/articles/4410598647316-Statement-of-Intent-SOI-and-Stewards-Sale-Tickets\" target=\"_blank\" rel=\"noreferrer noopener\">FAQ</a>.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>If your camp WILL RETURN in 2025…</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We’ll need to know your estimated camp size and number of Stewards Sale tickets you would like to purchase in March. We’d also like to know some basic information about your plans for the forthcoming event including any changes to your interactivity.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>If your camp WILL NOT RETURN in 2025 and you’d like to hold your standing…</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Fill out a handful of questions in the SOI for your camp to formally inform us that you will be taking 2025 off. If you do not fill out the SOI, we will assume you are skipping the 2025 event.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Any camp that has been in good standing for at least 3 events as a theme camp will be guaranteed at least the same number of tickets you most recently received as a camp if your camp returns within the next two years.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you don’t meet the 3-year requirement for guaranteed placement and tickets, your good standing will be held for up to 2 years. You will be eligible as a returning camp to receive tickets, but the amount will be determined upon your return.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><em>Note: Completing the SOI will give you access to tickets, but you must still complete the Placed Camp Questionnaire that opens in February for your camp to be placed in BRC.&nbsp;</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Thank you for all you have contributed to Black Rock City in 2024!&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The BRC Placement Team</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"mailto:contact@seed.test\" target=\"_blank\" rel=\"noreferrer noopener\">contact@seed.test</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Mycodelic Forest’s 2024 Snapshots</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong>Neighborhood Feedback&nbsp;</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><em>Placement collects neighbor feedback through the annual Neighborhood Feedback Form that we send out to all camp leaders in September, your self-submitted Post-playa Report, and from direct contact on playa or by email. The responses are aggregated from these sources.&nbsp;</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Favorite Camp</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>Not all camps received a shoutout as a favorite camp and many delightful experiences may never get mentioned. We do not view the results as representative and are sharing this so that you can get some sense of how you were viewed by other participants.&nbsp;</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>[Number of times your camp was mentioned as a favorite camp]: </strong>No mentions</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>[</strong><strong>What aspects of your camp’s interactivity were appreciated?] </strong><em>(All text responses are included, separated by a vertical bar. Not all survey respondents chose to elaborate.) </em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>N/A</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Non-Interactive and Un-neighborly Camps</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>People inform us if there were any camps that appeared to not provide interactivity or behaved in an un-neighborly fashion. Multiple mentions from the same camp were tallied as one.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>[</strong><strong>Number of times your camp was mentioned as…]</strong><!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>“non-interactive”:  </strong>No mentions</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>“un-neighborly behavior”: </strong>No mentions</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>[</strong><strong>What specific behaviors were cited as un-neighborly?]</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>(<em>Survey respondents could choose from a multi-select list. All responses were tallied and included. Not all survey respondents chose to pick from the list.): </em>N/A</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>[</strong><strong>Number of complaints for </strong><strong><em>Music/sound too loud (i.e. so loud that you can\'t have a conversation if you were standing in the middle of the street in front of the camp)</em></strong><strong>]</strong> N/A</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong>Placement’s Exploration and Engagement Research Squad (PEERS)</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><em>Placement’s Exploration and Engagement Research Squad (PEERS) is made up of volunteers from all over Black Rock City who visit theme camps and neighborhoods. Many are theme camp organizers themselves and contribute their time because they love getting to know other camps. PEERS are not evaluators and do not provide ratings for camps during their visit. Because they visit only once and visits are brief, we understand that their observations are not necessarily representative of your entire camp.&nbsp;</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[</strong><strong>Number of other camps that named your camp as a favorite to PEERS?] </strong>1 mentions</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[</strong><strong>Did PEERS volunteers rate your camp as…]&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>“open and inviting”: </strong>Yes</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>“friendly and welcoming to all”: </strong>Yes</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>“having obvious frontage”: </strong>Yes</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>“being lit at night”: </strong>N/A</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->','Mycodelic Forest’s 2024 Standing with Placement','','publish','open','open','','mycodelic-forests-2024-standing-with-placement','','','2025-02-02 16:36:11','2025-02-03 00:36:11','',0,'https://wordpress.mycodelicforest.org/?p=236',0,'post','',0),(240,1,'2025-02-02 20:55:21','2025-02-03 04:55:21','','IMG_4366','','inherit','open','closed','','img_4366','','','2025-02-02 20:55:21','2025-02-03 04:55:21','',0,'https://wordpress.mycodelicforest.org/wp-content/uploads/2025/02/IMG_4366.jpg',0,'attachment','image/jpeg',0),(242,1,'2025-02-03 12:06:25','2025-02-03 20:06:25','<!-- wp:paragraph -->\n<p>If you are interested in attending Burning Man 2025 with the Mycodelic Forest please let Lowell know ASAP and then get yourself registered for the \'Today\' sale. We\'ve been given almost no notice with this accelerated ticket timeline, but hey you gotto do what you gotto do to go to burning man right?<br><br>The \'Today\' sale registration will be open from today February 3rd to February 11th. The <code>Today</code>` sale will be on the 12th.<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Click here to see more information about Burning Man Ticket registration and sales <a href=\"https://tickets.burningman.org\">https://tickets.burningman.org</a><br><br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Today Sale Registration is Open','','publish','open','open','','today-sale-registration-is-open','','','2025-02-03 12:06:27','2025-02-03 20:06:27','',0,'https://wordpress.mycodelicforest.org/?p=242',0,'post','',0),(245,1,'2025-02-04 12:16:59','2025-02-04 20:16:59','<!-- wp:paragraph -->\n<p>Dear Camp Lead,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Over the weekend, Burning Man Project announced the pricing structure for the various ticket sales to Black Rock City 2025 and held a town hall meeting for our cultural collaborators that you may have attended. The announcement led to some confusion so&nbsp;<a href=\"https://email.burningman.org/t/t-l-shhxa-ttirxhtjj-r/\" target=\"_blank\" rel=\"noreferrer noopener\">Charlie Dolman, Event Operations Director, has written a letter to provide more clarity about ticket pricing levels</a>, which is also copied below.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Please read through this entire email as there are also some helpful reminders from Placement after Charlie\'s email.&nbsp;We hope this can help you and your campmates plans for how to approach the various ticket sales in the coming months.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><em>Hello Friends:</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>I hope you’re all having a great start to your week, and had a fantastic weekend.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>I know many of you joined the Town Hall on Saturday, and I’ve heard a lot of questions that have popped up about the tiered ticketing model and pricing availability for the Stewards Sale (starting March 5th). I’d like to apologize that our communication to you on Saturday wasn’t clearer and more transparent and that the ticket page doesn’t have what you are looking for. Hopefully, this email will be able to answer your questions. Please feel free to pass the answers to these questions along to the members of your groups.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><em>1- What prices will be available in the Stewards Sale?</em></strong><br><em>All of the price points available in the Today Sale will be available in the Stewards Sale. I know folks are worried that all of lower priced ($550 and $650) tickets will sell out in the Today Sale, and none will be available in the Stewards Sale, but that will not be the case as we have set aside an allocation of each of these tiers of tickets specifically for the Stewards Sale.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><em>2- Will groups be given tiered allocations? I.e. When your department assigns a ticket allocation to a group lead for the Stewards Sale, will a group be given access to X $550 tickets, Y $650 tickets, X $750 tickets, etc.</em></strong><br><em>No, when your group lead (theme camp, mutant vehicle, art crew, regional, etc.) is given an allocation from your Burning Man Project point person or department you will still be given the same kind of overall summary allocation you were in 2024. When someone enters the Stewards Sale to purchase tickets, they’ll then have the opportunity to select the ticket tier at which they’d like to purchase. That does mean that the $550 ticket is extremely likely to sell out very quickly in the Stewards Sale. However, we have allocated enough $650 tickets to ensure that ALL invitees in the Stewards Sale can purchase at that price if they wish to do so. However, we know some camps have members that can pay more, and we appreciate this consideration. This is very important to build our organic ecosystem for long term survival.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><em>3- Why aren’t Stewards being given guaranteed access to $550 tickets?</em></strong><br><em>Based on our budgetary constraints going into 2025, we had the option of either setting all of our tickets to $720 this year, or re-introducing our old tiered pricing and allowing for choice in pricing. (By the way, yes we used to do tiered pricing - the last time we did was in 2011.)</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>The $550 ticket (a reduction of last year’s $575 ticket price)&nbsp; is being introduced this year to encourage participation in Black Rock City for those who may not have previously thought they could due to price, location, or access. We will also hold back tickets at the $550 tier to continue with the cultural outreach represented by the new “initiatives:” Renaissance Champions and Rising Sparks. This means groups or individuals might still have access to those tickets if they aren’t secured in the Stewards Sale.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>While we are making $550 tickets available in all of our public sales on a limited basis, we want to encourage those who can purchase tickets at a higher tier to help support those who need to purchase tickets at a lower tier. The actual cost per-participant to put on Black Rock City is quite a bit higher than either $550 or $650, and we’re counting on our community to ensure that those that need to are able to access the event at a reasonable ticket price.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><em>4- Can I join the Today Sale to increase my chances of getting the lower price ticket?</em></strong><br><em>Yes, if you choose to participate in the Today Sale, you will also be able to participate in the Stewards Sale. Please keep in mind that access to tickets in the Stewards Sale is guaranteed, while tickets in the Today Sale are first come, first served. So you’ll probably have a smoother and faster purchase experience in the Stewards Sale.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><em>5- I heard about access to single buyer bulk sales. How do we activate that and how does that work with different tiers?</em></strong><br><em>With little exception single buyer bulk sales during the Stewards Sale will feature tickets at the $650 tier, or a combination of $650 tickets and a higher tier (up to you). The single buyer bulk sales&nbsp;are transacted through group leads of specific and known camps, vehicle groups, art collectives, etc. Talk to your Burning Man Project point person BEFORE the Stewards Sale to find out how to access this option. We want to make group sales easy for you.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><em>6- Why aren’t you sharing how many tickets are available in each tier??</em></strong><br><em>We’re not sharing tier allotments because we don’t want to share specific numbers and then have to make a change down the line. Right now we have to start sales and get things going. We ideally want to be able to sell MORE tickets under the “per person” event production cost (which was $749), and that’s the message and goal we are firmly working towards now and into future events.</em><br><br><em>We are aiming to sell at least as many Black Rock City tickets as what we sold last year. So we have to start with a model that has some tickets in each sale at $550, the majority at $650 and $750, and some at $950 and $1500. It is vital to how we are operating as a community economy to have those who can pay more pay more - this permits us to have lower cost tickets underwritten by ourselves and not by sponsorship. We want to be able to offer more lower cost tickets later in the season if we sell out the allotments for the higher priced tiers in the first few sales. But, again, that’s dependent upon people paying what they can.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>I applaud those of you who have reached out for clarification. We’re excited to get 2025 rolling and so deeply appreciative of everything you do!</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>Yours in Dust,</em><br>Charlie Dolman,Event Operations Director</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>We’d also like to offer some additional clarification and reminders for theme camps:</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Vehicle passes were not announced in your theme camp’s Stewards Sale ticket allocation email by mistake. <strong>Please assume that your camp has access to purchase <u>half</u> the number of vehicle passes as tickets.</strong> So if you were allocated 10 Stewards Sale tickets, you also will be allocated 5 vehicle passes.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Only purchase as many tickets as you need, even if you\'ve been allocated more than you need. </strong>Your theme camp does not need to purchase all the Stewards Sale tickets allocated to you. If your campmates are able to secure tickets before the Stewards Sale or change their mind and no longer want to attend BRC 2025, you do not need to purchase the full amount of tickets allocated to you. Any tickets purchased in excess of what you need unfortunately cannot be refunded so we don’t wish for you to be on the hook for extra tickets. If you find later in the season that you still need tickets, you can contact us at <a href=\"mailto:contact@seed.test\" target=\"_blank\" rel=\"noreferrer noopener\">contact@seed.test</a> by late May and we may be able to help.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Ticket purchasing at the varying price levels does not impact your camp’s standing</strong> with the Placement Team or where we map you in BRC 2025. Purchasing higher priced tickets does not mean your camp will receive preferential treatment, and purchasing lower priced tickets will not lead to a lower preference or standing.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>The Placed Camp Questionnaire (PCQ) is opening on February 19 and due March 27</strong>. Please be sure to complete that so that we can get the details we need in order to map your theme camp into BRC this year. Submitting a Statement of Intent last month does not substitute for submitting a PCQ, so please remember to carve out time to complete a questionnaire for 2025.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>If your theme camp decides at any point this year to cancel your plans for the year, </strong>please contact us at <a href=\"mailto:contact@seed.test\" target=\"_blank\" rel=\"noreferrer noopener\">contact@seed.test</a> and be sure to include your camp name in the subject line so we can update our records. The sooner we know, the better we can adapt the map for BRC this year. We’ll miss you but understand that things happen, and canceling will not impact your standing with Placement. </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Placement is only responsible for allocating tickets to theme camps, but not the actual ticket purchasing process. If you need any assistance in the ticket purchasing process for any of the sales, please email <a href=\"mailto:contact@seed.test\" target=\"_blank\" rel=\"noreferrer noopener\">contact@seed.test</a>. </li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Good luck!<br><em>The 2025 Placement Team</em></p>\n<!-- /wp:paragraph -->','Updated information about Burning Man Tickets and Sales','','publish','open','open','','updated-information-about-burning-man-tickets-and-sales','','','2025-02-04 12:17:00','2025-02-04 20:17:00','',0,'https://wordpress.mycodelicforest.org/?p=245',0,'post','',0),(266,1,'2025-02-18 21:22:30','2025-02-19 05:22:30','<!-- wp:gravityforms/form {\"formId\":\"6\",\"inputPrimaryColor\":\"#204ce5\"} /-->','Join Us','','publish','closed','closed','','join-us','','','2025-02-18 21:22:32','2025-02-19 05:22:32','',0,'https://wordpress.mycodelicforest.org/?page_id=266',0,'page','',0),(270,1,'2025-02-19 14:48:11','2025-02-19 22:48:11','<!-- wp:paragraph -->\n<p>Hello Trevor,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We’re writing to let you know that the&nbsp;<a href=\"https://profiles.burningman.org/participate/brc\" target=\"_blank\" rel=\"noreferrer noopener\">2025 Placed Camp Questionnaire</a>&nbsp;(PCQ) will be opening up today (February 19), accessible by logging onto Burner Profiles, and is due on Thursday, March 27 at 12pm PT / 3pm ET / 9pm CET.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We also want to let you know that Mycodelic Forest will be Fast Tracked and have a shorter form and experience than you may be used to. We’ve narrowed down the number of questions Fast Tracked camps need to submit to the most essential information that’s needed. If you’d like to see a sample of the PCQ’s questions, you can view a sample&nbsp;<a href=\"https://tinyurl.com/samplethemecamppcq\" target=\"_blank\" rel=\"noreferrer noopener\">here</a>&nbsp;(pages 5-23).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Who qualifies for Fast Track?</strong>&nbsp;Theme camps are Fast Tracked if they have been placed and in good standing for the last 3 events they’ve attended and without any issues. Theme camps who have been not in good standing or in limited standing, received conditional placement, or have not been a placed camp for at least 3 years will need to complete the standard set of questions asked of theme camps applying for Placement. You will be alerted that you’re on the Fast Track when you begin completing your PCQ in Burner Profiles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Please note that the&nbsp;current camp lead&nbsp;on file must fill out the PCQ in order for the pre-population and the Fast Track path to take effect. If someone else will be submitting the PCQ for your theme camp this year, please email us at&nbsp;<a href=\"mailto:contact@seed.test\" target=\"_blank\" rel=\"noreferrer noopener\">contact@seed.test</a>&nbsp;so we can update the camp lead&nbsp;<em>before</em>&nbsp;they start a form so we can be sure that it links properly for them to receive the Fast Track experience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Thank you for all your hard work as a theme camp and setting the bar for in-camp interactivity in Black Rock City! We can’t wait to see what you have in store for this year!<br><em>The 2025 Placement team</em></p>\n<!-- /wp:paragraph -->','Mycodelic Forest is Fast Tracked for the 2025 Placed Camp Questionnaire','','publish','open','open','','mycodelic-forest-is-fast-tracked-for-the-2025-placed-camp-questionnaire','','','2025-02-19 14:48:13','2025-02-19 22:48:13','',0,'https://wordpress.mycodelicforest.org/?p=270',0,'post','',0),(273,1,'2025-02-27 14:45:35','2025-02-27 22:45:35','<!-- wp:paragraph -->\n<p><strong>The Stewards Sale invitation form closes FRIDAY, February 28 @ 12pm PST!</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dear Trevor,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Thank you for being part of the Best Burning Man ever; your role as a leader and seed to distribute tickets for the event are valued. We thought we’d send a little reminder:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>The Stewards Sale invitation form in your&nbsp;<a href=\"https://email.burningman.org/t/t-l-skdidtk-ttkrsurjy-y/\" target=\"_blank\" rel=\"noreferrer noopener\">Burner Profile</a>&nbsp;closes on Friday, February 28, 2025 at 12pm (noon) PST.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>As the point person for your project, you alone are responsible for inviting your people. Listing your group members in this form is the only way to get your group into this sale! You’re not required to assign an invitation to yourself, but if you personally intend to buy tickets in this sale, you must assign an invitation to yourself.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Each person you successfully invite to the sale will receive their registration confirmation email by end of day<strong>&nbsp;Sunday, March 2, 2025</strong>. Please let your invitees know they will not receive a confirmation email until then.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Questions about your group’s allocation?</strong>&nbsp;Please get in touch directly with the team issuing your allocation (Placement, DMV, Art, etc.).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>In gratitude to all you do;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yours in dust,&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Burning Man Ticketing</p>\n<!-- /wp:paragraph -->','2025 Stewards Sale Invitation Form Closing','','publish','open','open','','2025-stewards-sale-invitation-form-closing','','','2025-02-27 14:45:36','2025-02-27 22:45:36','',0,'https://wordpress.mycodelicforest.org/?p=273',0,'post','',0),(275,1,'2025-02-27 20:24:28','2025-02-28 04:24:28','<!-- wp:gravityforms/form {\"formId\":\"6\",\"ajax\":true,\"inputPrimaryColor\":\"#204ce5\"} /-->','Profile','','publish','closed','closed','','profile','','','2025-02-28 12:54:49','2025-02-28 20:54:49','',0,'https://wordpress.mycodelicforest.org/?page_id=275',0,'page','',0);
